import sys
input = sys.stdin.read

def count_less_equal(x, n, m):
    count = 0
    for i in range(1, n + 1):
        count += min(x // i, m)
    return count

def find_kth_largest(n, m, k):
    left, right = 1, n * m
    while left < right:
        mid = (left + right) // 2
        if count_less_equal(mid, n, m) < k:
            left = mid + 1
        else:
            right = mid
    return left

data = input().strip().split()
n, m, k = map(int, data)
result = find_kth_largest(n, m, k)
print(result)
